// Category B — the overlay that frames a live camera for scanning: a dimmed surround, a clear window
// with corner brackets (a QR or barcode) or a ring (a face), and a caption that says what to do and
// what happened: a counter, a kiosk or an ID check. It owns no camera: the consumer passes the `<video>` (or a still) as `children`, and it fills the frame.
//
// `shape` sets the window: `square` for a QR code, `wide` for a barcode, `circle` for a face. The
// caption is a polite live region on its own surface, so a change ("인식했어요") is announced and stays
// legible over any image; the window and brackets are decorative. Name the whole with `aria-label` ("QR 스캔"), since the camera image carries no text.
import { Fragment, cloneElement, isValidElement } from "react";
import type { ReactElement, ReactNode, Ref } from "react";
import "./ScanFrame.css";

export interface ScanFrameProps {
  /**
   * Size axis: the caption's type rung. `large` on a kiosk read at arm's length.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /**
   * The window's shape: `square` for a QR code, `wide` for a barcode, `circle` for a face.
   *
   * @default "square"
   */
  shape?: "square" | "wide" | "circle";
  /** The camera feed or a still, filling the frame: one media element, or a Fragment around one. */
  children?: ReactElement<{ className?: string }> | null | false;
  /** The line under the window: the instruction, then any change while scanning. Announced politely. */
  caption?: ReactNode;
  /** Name of the scan area, e.g. "QR 스캔". */
  "aria-label": string;
  /** Additional class (optional). sd-scan-frame is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * Gives the media child the feed's fit class, so an unsized <video> or <img> fills the frame. Takes one
 * media element, or a Fragment around one (fitted through, once); anything else is left unchanged.
 */
function fit(children: ReactNode): ReactNode {
  if (!isValidElement<{ className?: string; children?: ReactNode }>(children)) return children;
  if (children.type === Fragment) {
    // The Fragment's own child, not Children.toArray's copy: toArray re-keys it (".0"), and a new key
    // would remount a <video> when children switch between <video/> and <><video/></>.
    // Holes ({cond && x}) are skipped, so <><video/>{false}</> still fits its video.
    const kids = children.props.children;
    const real = Array.isArray(kids) ? kids.filter((k) => k != null && typeof k !== "boolean") : [kids];
    const only = real.length === 1 ? real[0] : undefined;
    if (!isValidElement(only) || only.type === Fragment) return children;
    return Array.isArray(kids) ? cloneElement(children, {}, ...kids.map((k) => (k === only ? fit(only) : k))) : cloneElement(children, {}, fit(only));
  }
  const own = children.props.className;
  return cloneElement(children, { className: own ? `sd-scan-frame__media ${own}` : "sd-scan-frame__media" });
}

export function ScanFrame({ size = "medium", shape = "square", children, caption, "aria-label": ariaLabel, className, ref }: ScanFrameProps) {
  return (
    <div
      ref={ref}
      role="group"
      aria-label={ariaLabel}
      className={className ? `sd-scan-frame ${className}` : "sd-scan-frame"}
    >
      <div className="sd-scan-frame__feed">{fit(children)}</div>
      <div className="sd-scan-frame__overlay" aria-hidden="true">
        <div className="sd-scan-frame__window" data-shape={shape}>
          {shape !== "circle" && (
            <>
              <span className="sd-scan-frame__corner" data-corner="start-start" />
              <span className="sd-scan-frame__corner" data-corner="start-end" />
              <span className="sd-scan-frame__corner" data-corner="end-start" />
              <span className="sd-scan-frame__corner" data-corner="end-end" />
            </>
          )}
        </div>
      </div>
      <p className={`sd-scan-frame__caption sd-type-body-${size}-emphasized`} aria-live="polite">
        {caption}
      </p>
    </div>
  );
}

/* The feed fills the frame; the overlay dims all of it but the centred window, whose surround is a
   spread shadow, so the window stays clear without a mask. Brackets mark a QR or barcode window's
   corners; a face window is a ring. */
.sd-scan-frame {
  position: relative;
  display: grid;
  overflow: clip;
  inline-size: 100%;
  block-size: 100%;
  min-block-size: var(--sd-scan-frame-min-height);
  background: var(--sd-scan-frame-background);
  /* The window is sized by the frame, not the viewport, so a short wide frame keeps it inside. */
  container-type: size;
}

.sd-scan-frame__feed {
  position: absolute;
  inset: 0;
  display: grid;
}

/* The media the consumer passes (a <video> or a still) fills the frame and keeps its aspect, cropped. */
.sd-scan-frame__media {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

.sd-scan-frame__overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

.sd-scan-frame__window {
  position: relative;
  box-shadow: 0 0 0 100vmax var(--sd-scan-frame-scrim);
}
.sd-scan-frame__window[data-shape="square"] {
  inline-size: min(60cqi, 60cqb);
  aspect-ratio: 1;
  border-radius: var(--sd-scan-frame-window-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-scan-frame__window[data-shape="wide"] {
  inline-size: min(80cqi, 160cqb);
  aspect-ratio: 2;
  border-radius: var(--sd-scan-frame-window-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-scan-frame__window[data-shape="circle"] {
  inline-size: min(60cqi, 60cqb);
  aspect-ratio: 1;
  border-radius: var(--sd-scan-frame-ring-radius);
  corner-shape: round;
  border: var(--sd-scan-frame-mark-width) solid var(--sd-scan-frame-mark);
}

.sd-scan-frame__corner {
  position: absolute;
  inline-size: var(--sd-scan-frame-corner-length);
  block-size: var(--sd-scan-frame-corner-length);
  border-color: var(--sd-scan-frame-mark);
  border-style: solid;
  border-width: 0;
}
.sd-scan-frame__corner[data-corner="start-start"] {
  inset-block-start: 0;
  inset-inline-start: 0;
  border-block-start-width: var(--sd-scan-frame-mark-width);
  border-inline-start-width: var(--sd-scan-frame-mark-width);
  border-start-start-radius: var(--sd-scan-frame-window-radius);
  corner-start-start-shape: superellipse(var(--sd-radius-curve));
}
.sd-scan-frame__corner[data-corner="start-end"] {
  inset-block-start: 0;
  inset-inline-end: 0;
  border-block-start-width: var(--sd-scan-frame-mark-width);
  border-inline-end-width: var(--sd-scan-frame-mark-width);
  border-start-end-radius: var(--sd-scan-frame-window-radius);
  corner-start-end-shape: superellipse(var(--sd-radius-curve));
}
.sd-scan-frame__corner[data-corner="end-start"] {
  inset-block-end: 0;
  inset-inline-start: 0;
  border-block-end-width: var(--sd-scan-frame-mark-width);
  border-inline-start-width: var(--sd-scan-frame-mark-width);
  border-end-start-radius: var(--sd-scan-frame-window-radius);
  corner-end-start-shape: superellipse(var(--sd-radius-curve));
}
.sd-scan-frame__corner[data-corner="end-end"] {
  inset-block-end: 0;
  inset-inline-end: 0;
  border-block-end-width: var(--sd-scan-frame-mark-width);
  border-inline-end-width: var(--sd-scan-frame-mark-width);
  border-end-end-radius: var(--sd-scan-frame-window-radius);
  corner-end-end-shape: superellipse(var(--sd-radius-curve));
}

/* The caption sits on its own surface: the camera image can be any brightness, so text drawn
   straight on it could not promise contrast. Empty, it leaves the flow but stays in the accessibility
   tree, so its first message is announced. */
.sd-scan-frame__caption {
  position: relative;
  align-self: end;
  justify-self: center;
  margin: var(--sd-scan-frame-caption-margin);
  padding: var(--sd-scan-frame-caption-padding);
  border-radius: var(--sd-scan-frame-caption-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-scan-frame-caption-background);
  text-align: center;
  color: var(--sd-scan-frame-caption-foreground);
}
.sd-scan-frame__caption:empty {
  position: absolute;
  margin: 0;
  padding: 0;
  background: transparent;
}
